Input: {"question": "When did Henry St John-Mildmay become the Baronet?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0403-c03155277f52:d00", "start": 0, "end": 184, "text": "Sir Henry St John-Mildmay, 3rd Baronet Sir Henry Paulet St John-Mildmay, 3rd Baronet (30 September 1764 – 11 November 1808), of Dogmersfield Park, Hampshire, was an English politician."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0403-c03155277f52:d00", "start": 185, "end": 369, "text": "St John was the only son of Sir Henry Paulet St John, Bt and his wife Dorothea Maria Tucker, daughter of Abraham Tucker of Betchworth Castle, Surrey, and was born on 30 September 1764."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0403-c03155277f52:d00", "start": 370, "end": 430, "text": "He succeeded to the baronetcy and Dogmersfield Park in 1784."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0403-c03155277f52:d00", "start": 431, "end": 545, "text": "He was a Member (MP) for Westbury 1796 – 1802, for Winchester 1802–1807 and for Hampshire 1807 – 11 November 1808."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0403-c03155277f52:d00", "start": 546, "end": 585, "text": "He married, in 1786, Jane, the daughter"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 0, "end": 186, "text": "Sir Henry St John-Mildmay, 4th Baronet Sir Henry St John Carew St John-Mildmay, 4th Baronet (15 April 1787 – 17 January 1848), of Dogmersfield Park, Hampshire, was an English politician."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 187, "end": 344, "text": "He was the son of Sir Henry St John-Mildmay, 3rd Baronet of Dogmersfield Park and educated at Winchester School (1798-1802) and Christ Church, Oxford (1805)."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 345, "end": 438, "text": "He was a Member of Parliament (MP) for Winchester 1807–1818 and Mayor of Winchester for 1808."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 439, "end": 490, "text": "He succeeded his father in the baronetcy on 11 Nov."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 491, "end": 496, "text": "1808."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 497, "end": 564, "text": "He married twice; firstly, in 1809, Charlotte, the daughter of Hon."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0403-c03155277f52:d01", "start": 565, "end": 605, "text": "Bartholomew Bouverie, with whom he had a"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0403-c03155277f52:d02", "start": 0, "end": 200, "text": "Sir Henry St John-Mildmay, 5th Baronet Sir Henry Bouverie Paulet St John-Mildmay, 5th Baronet (1810 – 16 July 1902), of Dogmersfield Park, Hampshire, was an English landowner and British Army officer."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0403-c03155277f52:d02", "start": 201, "end": 308, "text": "St John-Mildmay was born in 1810, the son of Sir Henry St John-Mildmay, 4th Baronet and Charlotte Bouverie."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0403-c03155277f52:d02", "start": 309, "end": 352, "text": "He succeeded his father as baronet in 1848."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0403-c03155277f52:d02", "start": 353, "end": 457, "text": "He was commissioned an officer in the 2nd Dragoon Guards, where he advanced to major before he resigned."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0403-c03155277f52:d02", "start": 458, "end": 549, "text": "He was later Commanding Officer and later Honorary Colonel of the North Hampshire Yeomanry."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0403-c03155277f52:d02", "start": 550, "end": 607, "text": "Serving as High Sheriff of Hampshire in 1862, he was also"}}, "candidates": [{"candidate_id": "C0", "answer": "1784", "card_ids": ["ramdocs-0403-c03155277f52:d00:c0"]}, {"candidate_id": "C1", "answer": "11 Nov. 1808", "card_ids": ["ramdocs-0403-c03155277f52:d01:c0"]}, {"candidate_id": "C2", "answer": "1848", "card_ids": ["ramdocs-0403-c03155277f52:d02:c0"]}], "original_cards": [{"doc_id": "ramdocs-0403-c03155277f52:d00", "card_id": "ramdocs-0403-c03155277f52:d00:c0", "entity": "Henry St John-Mildmay", "scope": "Baronetcy", "claim": "Henry St John-Mildmay became the Baronet in 1784.", "answer": "1784", "quote": "He succeeded to the baronetcy and Dogmersfield Park in 1784.", "original_document_number": 1}, {"doc_id": "ramdocs-0403-c03155277f52:d01", "card_id": "ramdocs-0403-c03155277f52:d01:c0", "entity": "Henry St John-Mildmay", "scope": "Baronet", "claim": "Henry St John-Mildmay became the Baronet on 11 Nov. 1808.", "answer": "11 Nov. 1808", "quote": "He succeeded his father in the baronetcy on 11 Nov. 1808.", "original_document_number": 2}, {"doc_id": "ramdocs-0403-c03155277f52:d02", "card_id": "ramdocs-0403-c03155277f52:d02:c0", "entity": "Henry St John-Mildmay", "scope": "became the Baronet", "claim": "Henry St John-Mildmay became the Baronet in 1848.", "answer": "1848", "quote": "He succeeded his father as baronet in 1848.", "original_document_number": 3}], "initial_answers": ["1784", "1808", "1848"]}
